def allowed_file(filename, allowed):
    return "." in filename and filename.rsplit(".",1)[1].lower() in allowed

app = Flask(__name__)
app.secret_key = os.environ.get("GAUR_CRM_SECRET", "GAUR-CRM-LOCAL-2026-CHANGE-ME")
