            allocated_c=con.execute("SELECT COUNT(*) c FROM leads WHERE company_code=? AND COALESCE(NULLIF(assigned_at,''),imported_at,'') BETWEEN ? AND ? AND assigned_am IS NOT NULL",(code,month_start,month_end_ts)).fetchone()["c"]
            unallocated_c=con.execute("SELECT COUNT(*) c FROM leads WHERE company_code=? AND COALESCE(NULLIF(assigned_at,''),imported_at,'') BETWEEN ? AND ? AND assigned_am IS NULL",(code,month_start,month_end_ts)).fetchone()["c"]
            hot_c=con.execute("SELECT COUNT(*) c FROM leads WHERE company_code=? AND COALESCE(NULLIF(assigned_at,''),imported_at,'') BETWEEN ? AND ? AND COALESCE(interest_score,0)>=71",(code,month_start,month_end_ts)).fetchone()["c"]
            warm_c=con.execute("SELECT COUNT(*) c FROM leads WHERE company_code=? AND COALESCE(NULLIF(assigned_at,''),imported_at,'') BETWEEN ? AND ? AND COALESCE(interest_score,0) BETWEEN 50 AND 70",(code,month_start,month_end_ts)).fetchone()["c"]
